      for (let i = 0; i < n - 1; i++) { const x = -((n - 1) * 5.5) / 2 + (i + 0.5) * 5.5; c.put('bench', x, 1.4, PI); }
      for (const s of [-1, 1]) c.put('lampStem', s * (c.w / 2 - 0.7), c.d / 2 - 0.7, 0);
